INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Региональная публичная власть: 414-ФЗ','В субъекте РФ зарегистрировано 430 тысяч избирателей. Какая численность депутатов регионального парламента соответствует федеральному диапазону?','["От 25 до 70 депутатов","От 15 до 50 депутатов","От 35 до 90 депутатов","От 45 до 110 депутатов"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В регионе зарегистрировано 750 тысяч избирателей. Каковы допустимые границы численности законодательного органа субъекта?','["25–70 депутатов","15–50 депутатов","35–90 депутатов","45–110 депутатов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В субъекте насчитывается 1,4 млн избирателей. Закон региона установил 30 депутатов. Как исправить положение?','["Установить не менее 25 и не более 70 депутатов","Сохранить 30 при согласии губернатора","Установить не менее 45 и не более 110 депутатов","Установить не менее 35 и не более 90 депутатов"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В регионе 2,3 млн зарегистрированных избирателей, а его устав предусматривает 40 депутатов. Каков установленный федеральный минимум?','["35 депутатов","40 депутатов","45 депутатов","50 депутатов"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Из 48 предусмотренных уставом мандатов замещены 31. Может ли законодательный орган субъекта начать осуществлять полномочия?','["Да, избрано более половины мандатов","Нет, избрано менее двух третей установленного числа депутатов","Да, если 31 депутат присутствует на заседании","Нет, нужно избрать исключительно все 48 депутатов"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В уставе субъекта закреплено 50 депутатов. Сколько необходимо избрать минимум для начала осуществления полномочий парламентом?','["34 депутата","33 депутата","25 депутатов","38 депутатов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Парламент субъекта назвали «Федеральным Собранием области». В чём нарушение 414-ФЗ?','["Название регионального парламента всегда должно быть «Дума»","Название выбирают только федеральным законом","Наименование обязательно содержит слово «Совет»","Наименование не может использовать словосочетания, составляющие основу названий федеральных органов"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Регион предлагает устанавливать структуру своего парламента распоряжением губернатора, не отражая её в уставе. Какой акт требуется?','["Письмо областного министра финансов","Регламент территориальной избирательной комиссии","Конституция или устав субъекта РФ","Постановление Правительства РФ"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Какой срок полномочий депутатов регионального законодательного органа одного созыва предусмотрен 414-ФЗ?','["Четыре года","Пять лет","Шесть лет","Семь лет"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный парламент объявил себя временным органом, созываемым только для принятия бюджета. Соответствует ли это статье 7?','["Нет, законодательный орган является постоянно действующим","Да, если заседает минимум дважды за финансовый год","Да, если его созывает губернатор","Нет, парламент должен заседать только в период выборов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Депутаты хотят самостоятельно управлять исполнением всего бюджета субъекта через свой финансовый отдел. Какое ограничение предусмотрено?','["Можно распоряжаться любой расходной статьёй при принятии бюджета","Можно передать депутатам все полномочия финансового органа","Можно осуществлять расходы без бюджетной классификации","Нельзя распоряжаться средствами бюджета при исполнении, кроме средств на работу парламента и депутатов"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Как должно отражаться финансовое обеспечение законодательного органа субъекта в региональном бюджете?','["Только в составе неразделимого резерва губернатора","Исключительно в муниципальных бюджетах","Отдельно от иных расходов в соответствии с бюджетной классификацией","Как внебюджетное пожертвование политическим партиям"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В регионе повысилась численность избирателей и возникла обязанность привести количество депутатов к диапазону закона. Кто вносит проект поправок к уставу?','["Только территориальная избирательная комиссия","Высшее должностное лицо субъекта РФ","Главы всех муниципальных округов коллективно","Совет Федерации по собственной инициативе"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','При подтверждённом изменении численности избирателей губернатор предлагает поправку к уставу о численности парламента через 70 дней. Какой предельный срок подачи?','["Не позднее 45 дней после установления факта изменения","Не позднее 30 дней с принятия федерального закона","В течение 90 дней после избрания нового парламента","В течение 80 дней после факта изменения"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_404070/62b190188b57ec2d715aa1fbde91a4ec78fae72b/','Основание: статья 7 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Областной парламент намерен заменить принятие бюджета своим постановлением. Как правильно утверждается бюджет субъекта?','["Постановлением регионального парламента о внутреннем распорядке","Распоряжением губернатора после согласования с банком","Протоколом бюджетного комитета без пленарного голосования","Законом субъекта Российской Федерации"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональное правительство представляет ежегодный отчёт о деятельности. Какой орган должен его заслушать?','["Центральная избирательная комиссия","Конституционный Суд Российской Федерации","Законодательный орган соответствующего субъекта РФ","Только Совет Федерации"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Какой акт регионального парламента устанавливает порядок управления акциями субъекта в уставных капиталах организаций?','["Индивидуальное письмо депутата","Закон субъекта Российской Федерации","Внутренний приказ казначейства","Исключительно распоряжение главы муниципалитета"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Для назначения очередных выборов регионального законодательного органа требуется решение. Какой акт предусмотрен статьёй 8?','["Постановление законодательного органа субъекта","Федеральный конституционный закон","Постановление Конституционного Суда","Только муниципальный устав"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Депутаты субъекта определяют свой внутренний распорядок. Какой акт используют по статье 8?','["Отдельный региональный закон о каждом заседании","Приказ федерального министра внутренних дел","Указ Президента о графике парламентских заседаний","Постановление законодательного органа о регламенте"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Планируется установить порядок изменения административно-территориального устройства субъекта РФ. В какой форме решается вопрос?','["Протоколом заседания комиссии без принятия закона","Постановлением Совета Федерации о местном бюджете","Законом субъекта Российской Федерации","Распоряжением руководителя каждого муниципалитета"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В регионе принимают закон об установлении региональной налоговой льготы в пределах НК РФ. Кто осуществляет законодательное регулирование?','["Только региональное правительство своим регламентом","Законодательный орган субъекта РФ","Избирательная комиссия субъекта","Только собрание муниципальных старост"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Для утверждения соглашения об изменении границы между субъектами какой акт регионального парламента указан в статье 8?','["Постановление законодательного органа субъекта","Исключительно закон о федеральном бюджете","Письмо руководителя аппарата парламента","Решение комитета регионального правительства"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Законодательное собрание субъекта хочет предложить поправки к федеральному закону. Имеет ли оно право законодательной инициативы в Федеральном Собрании?','["Нет, только губернаторы имеют такое право","Да, но исключительно через муниципальные советы","Нет, участвовать могут только сенаторы","Да, это полномочие законодательного органа субъекта"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В регионе рассматривается утверждение бюджета территориального государственного внебюджетного фонда. Какая форма акта предусмотрена?','["Постановление областной избирательной комиссии","Распоряжение муниципальной администрации","Закон субъекта РФ","Регламент федерального министерства"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто определяет порядок проведения регионального референдума в пределах федеральных гарантий?','["Правительство РФ индивидуальным письмом","Законодательный орган субъекта законом субъекта","Конституционный Суд РФ при регистрации инициативы","Председатель территориальной комиссии приказом"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный депутат предлагает признать полномочием парламента отмену судебных решений по вопросам областной собственности. Соответствует ли это разграничению компетенций?','["Нет, судебные решения пересматриваются по судебным процедурам, а парламент контролирует установленный порядок распоряжения имуществом","Да, парламент пересматривает решения любого суда субъекта","Да, при согласии представительного органа муниципалитета","Да, если в бюджете предусмотрены расходы на судебный процесс"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Каким актом законодательный орган субъекта оформляет выражение недоверия высшему должностному лицу?','["Законом о налоговых льготах","Уставом муниципального образования","Решением коллегии региональной прокуратуры","Постановлением законодательного органа субъекта"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Как парламент субъекта участвует в регулировании передачи муниципалитетам отдельных государственных полномочий региона?','["Издаёт индивидуальное распоряжение казначейству без закона","Принимает федеральный конституционный закон","Принимает соответствующий закон субъекта в рамках полномочий","Утверждает уставы всех муниципалитетов вместо их представительных органов"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Каким образом законодательный орган субъекта определяет порядок стратегического планирования на территории региона?','["Только распоряжением руководителя каждого ведомства","Законом субъекта Российской Федерации","Исключительно ежегодным посланием Президента РФ","Решением региональной партийной конференции"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто вправе утвердить заключение и расторжение договоров субъекта РФ в установленном федеральным законом порядке?','["Законодательный орган субъекта посредством закона субъекта","Любая территориальная комиссия с правом совещательного голоса","Общественная организация, участвовавшая в обсуждении","Руководитель муниципального органа по своему усмотрению"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Какая форма решения законодательного органа субъекта предусмотрена для оформления его согласия на назначение должностного лица?','["Федеральный конституционный закон о назначении","Протокол общественных слушаний","Решение глав местных администраций","Постановление при наличии предусмотренной законом компетенции"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Может ли региональный парламент заслушивать информацию о деятельности территориального органа федерального ведомства?','["Нет, это исключительная прерогатива Правительства РФ","Нет, сведения федеральных ведомств всегда закрыты","Да, в пределах процедуры, установленной законом и регламентом","Да, но исключительно в форме регионального референдума"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 8','https://www.consultant.ru/document/cons_doc_LAW_404070/9063c081be721f16d3039b4675cb3c48e447d52e/','Основание: статья 8 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Депутат областной думы внёс проект закона субъекта РФ. Обладает ли он законодательной инициативой непосредственно по 414-ФЗ?','["Нет, необходима санкция Совета Федерации","Да, депутат регионального парламента входит в круг инициаторов","Да, но только если депутат одновременно является губернатором","Нет, инициатива принадлежит исключительно исполнительной власти"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Прокурор субъекта предложил законопроект областному законодательному собранию. Допускает ли статья 10 такую инициативу?','["Да, прокурор субъекта прямо назван субъектом законодательной инициативы","Нет, прокурор всегда действует только через суд","Да, но после федерального референдума","Нет, региональные законопроекты вносит только губернатор"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Муниципальный представительный орган внёс региональный законопроект. Какова его правовая возможность?','["Право есть только у глав муниципальных учреждений","Внести проект он может только в Государственную Думу РФ","Муниципалитет вправе принимать региональные законы самостоятельно","Ему принадлежит право законодательной инициативы в органе субъекта"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Сенатор от субъекта хочет напрямую внести проект в региональный парламент. Когда это допускается?','["Автоматически каждому сенатору без регионального регулирования","Только после назначения Председателем Правительства","Если право предоставлено конституцией или уставом субъекта РФ","Если сенатор предварительно избран депутатом Госдумы"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Гражданская инициативная группа хочет представить проект закона непосредственно в региональный парламент. Какое условие предусмотрено статьёй 10?','["Граждане всегда исключены из любых законодательных инициатив","Право граждан может быть закреплено конституцией или уставом субъекта","Гражданская инициатива возможна исключительно на федеральном уровне","Граждане вправе принимать закон без рассмотрения парламентом"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Губернатор попросил первоочередного рассмотрения своего законопроекта в региональном парламенте. Может ли такое требование опираться на 414-ФЗ?','["Да, проекты высшего должностного лица по его предложению рассматриваются первоочередно","Нет, все инициативы обязательно рассматриваются по времени поступления","Да, но только при отсутствии других проектов","Нет, приоритет предоставляется только прокурору субъекта"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Депутат внёс проект закона о новых региональных бюджетных расходах без представления губернатора или его заключения. Какое требование действует?','["Необходимо исключительно голосование Совета Федерации","Достаточно устной рекомендации областного министра","Такой проект вправе рассматривать только Конституционный Суд","Необходимо представление высшего должностного лица субъекта либо его заключение"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный устав устанавливает для губернатора срок подготовки заключения на бюджетный законопроект в десять дней. Какой нижний предел закреплён федеральным законом?','["Не менее десяти дней","Не менее сорока пяти дней","Не менее двадцати дней","Не менее трёх месяцев"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_404070/d481ffe2f68d1daf68a1ee1612a5e89e02c96f36/','Основание: статья 10 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','На заседании законодательного органа субъекта присутствует 45% установленного числа депутатов. Может ли заседание считаться правомочным?','["Да, если большинство присутствующих голосует за повестку","Нет, присутствовать должно не менее 50% установленного состава","Да, при согласии губернатора","Нет, присутствовать обязаны не менее двух третей депутатов"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный парламент собирается на правомочное заседание раз в полгода. Каков обязательный минимум частоты?','["Не реже одного раза в три месяца","Не реже одного раза в шесть месяцев","Не реже одного раза в год","Не реже одного раза в два месяца"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Новый парламент субъекта впервые собирается через сорок дней после избрания в правомочном составе. Какой максимум предусмотрен?','["Не позднее сорока пяти дней","Не позднее двух месяцев","Не позднее семи дней","Не позднее тридцати дней после избрания в правомочном составе"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Депутаты предлагают полностью закрыть все заседания регионального парламента внутренним решением без соблюдения предусмотренных оснований. Что является общим принципом?','["Безусловная закрытость всех парламентских заседаний","Обязательный закрытый режим для обсуждения любых законопроектов","Открытость заседаний с возможными законными исключениями","Открытость только заседаний бюджетного комитета"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный парламент приглашает руководителя федерального территориального органа. За какой минимум времени направляется приглашение с вопросами?','["Не позднее трёх дней до заседания","Не позднее семи дней до дня заседания","Не позднее десяти дней до заседания","Не позднее одного месяца до заседания"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Приглашённый руководитель территориального федерального органа не может присутствовать. За какой срок он должен уведомить парламент субъекта?','["Не позднее двух дней до заседания","Не позднее одного дня до заседания","Не позднее семи дней до заседания","В течение пяти дней после заседания"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Руководитель территориального органа не может выступить сам и предлагает должностное лицо, способное ответить депутатам. Какая процедура нужна?','["Автоматически направить любого сотрудника без уведомления","Отменить все будущие заседания по этой теме","Передать вопрос только в федеральный парламент","Согласовать замену или выступление на другом заседании с законодательным органом"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Сенатор РФ, представляющий субъект, хочет выступить в его законодательном органе. Какой принцип установлен статьёй 11?','["Выступление запрещено сенаторам до окончания мандата","Выступление допускается лишь при решении Правительства РФ","Участие и выступление допускаются в порядке регионального регламента","Выступление возможно только на федеральном референдуме"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Приглашённый депутатами руководитель исполнительного органа субъекта отказывается отвечать на вопросы, хотя регламент и режим тайны позволяют ответ. Какой порядок предусмотрен?','["Ответы допускаются исключительно в письменном виде после заседания","Выступление и ответы на вопросы в соответствии с регламентом с учётом охраняемой законом тайны","Руководители исполнительных органов субъекта никогда не выступают в парламенте","Ответы может давать только губернатор"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_404070/aa52065448edeb997087ef6f19f46231af52ab35/','Основание: статья 11 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Устав субъекта предусматривает 45 депутатов. Сколько голосов требуется минимум для принятия поправки к уставу?','["Не менее тридцати голосов","Не менее двадцати трёх голосов","Не менее двадцати девяти голосов","Не менее тридцати четырёх голосов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный парламент, состоящий из 40 депутатов, принимает поправку к уставу 26 голосами. Какова оценка?','["Достаточно, если присутствует половина состава","Достаточно при одобрении губернатором","Недостаточно, необходимо не менее 30 голосов","Недостаточно, нужно не менее 27 голосов"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Законодательный орган субъекта численностью 50 депутатов принимает обычный закон 25 голосами. Какое правило применяется?','["Достаточно ровно половины при отсутствии голосов против","Необходимо большинство от присутствующих","Необходимо большинство от установленного числа, то есть минимум 26","Необходимо две трети, то есть 34"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Субъект предложил принять региональный закон после единственного чтения. Какой минимум предусмотрен 414-ФЗ?','["Только одно чтение","Не менее двух чтений","Не менее трёх чтений для всех региональных законов","Не менее четырёх чтений"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный парламент оформил принятие закона устной резолюцией председателя без постановления. Какое оформление требуется?','["Решение о принятии закона оформляется постановлением законодательного органа","Решение оформляется только указом губернатора","Достаточно стенограммы заседания","Решение обязательно оформляет Совет Федерации"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Как принимается постановление регионального парламента по общему правилу 414-ФЗ?','["Большинством только от присутствующих депутатов","Большинством из числа всех зарегистрированных избирателей","Двумя третями сенаторов Российской Федерации","Большинством от установленного числа депутатов"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В законодательном органе субъекта 75 депутатов. Каким большинством принимается обычный закон при отсутствии специального правила?','["Не менее 37 голосов","Не менее 50 голосов","Не менее 38 голосов","Не менее 56 голосов"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','В региональном парламенте 60 депутатов, за новую редакцию устава голосуют 39. Какой вывод?','["Достаточно: закон принят большинством от установленного числа","Недостаточно: квалифицированное большинство требует минимум 40","Недостаточно: необходимо единогласие всех депутатов","Достаточно при подтверждении губернатором"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Можно ли оформить отклонение регионального законопроекта одним голосованием без постановления парламента?','["Нет, решение об отклонении проекта оформляется постановлением","Да, отклонённые проекты не нуждаются в оформлении","Да, решение автоматически фиксирует областная прокуратура","Нет, такое решение оформляется лишь указом Президента"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_404070/627085231473fa9ce99d2d614ebd99416e91c893/','Основание: статья 12 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кандидату на должность губернатора 29 лет. Какое требование нарушено?','["Кандидат должен быть не моложе тридцати пяти лет","Возрастного требования к губернаторам не существует","Минимальный возраст составляет двадцать пять лет","Возраст кандидата должен быть не менее тридцати лет"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кандидат на должность главы субъекта постоянно проживает за пределами Российской Федерации. Что устанавливает статья 20?','["Место проживания значения не имеет","Требуется проживание только на территории избирающего субъекта 10 лет","Требуется постоянное проживание в Российской Федерации","Достаточно регистрации в любом иностранном государстве"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Планируется установить трёхлетний срок полномочий губернатора в уставе субъекта. Какой срок установлен 414-ФЗ?','["Четыре года","Пять лет","Шесть лет","Семь лет"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кандидат на должность главы региона имеет вид на жительство другого государства. Каково федеральное ограничение?','["Наличие иностранного документа о постоянном проживании препятствует избранию","Вид на жительство допустим при согласии регионального парламента","Допустимо при неиспользовании документа два года","Допустимо по заявлению самого кандидата"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто руководит исполнительной властью в субъекте и определяет структуру её органов?','["Председатель регионального законодательного органа","Председатель Конституционного Суда РФ","Только федеральный министр финансов","Высшее должностное лицо субъекта РФ"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Какие базовые названия должности главы субъекта допускает статья 20?','["Только «Президент» субъекта","Только «Председатель Совета Федерации» региона","«Глава» или «Губернатор» с указанием субъекта","Только «Председатель региональной думы»"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Регион намерен официально именовать своего губернатора «Президентом республики». Какое ограничение действует?','["Такое название обязательно для всех республик","Дополнительное название не может повторять наименование должности Президента РФ","Название губернатора определяется только Правительством РФ","Федеральный закон допускает любое наименование без ограничений"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Как может быть избран глава субъекта Российской Федерации по статье 20?','["Гражданами либо депутатами законодательного органа субъекта","Только прямым всенародным голосованием без исключений","Исключительно назначением федеральным Правительством","Только местными главами на съезде муниципалитетов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','С какого юридического момента отсчитывается срок полномочий нового губернатора?','["Со дня выдачи удостоверения кандидата","С даты официального назначения выборов","С даты первой публикации предвыборной программы","Со дня принесения им присяги"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Глава региона хочет не приносить присягу, считая избрание достаточным для начала исполнения полномочий. Что предусматривает 414-ФЗ?','["Присяга предусмотрена исключительно для Президента РФ","Присягу может заменить постановление финансового органа","Вступление в должность связано с присягой народу и конституционным основам","Присяга нужна только избранным региональным парламентом"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 20','https://www.consultant.ru/document/cons_doc_LAW_404070/c3dc1bae742d3abff618d08723f4f46a03080c4c/','Основание: статья 20 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Губернатор одновременно избран депутатом Государственной Думы. Допускает ли закон совмещение?','["Да, если депутат работает без оплаты","Нет, эти государственные должности несовместимы","Да, с согласия председателя региональной думы","Да, если губернатор не участвует в голосованиях"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Глава субъекта получил предложение преподавать в государственном университете. Допустима ли оплачиваемая деятельность такого рода по общему правилу?','["Да, преподавательская, научная и иная творческая деятельность относятся к исключениям","Нет, любая оплачиваемая деятельность запрещена","Да, лишь с разрешения регионального парламента","Нет, исключения предусмотрены исключительно для федеральных министров"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Губернатор хочет входить в наблюдательный совет иностранной некоммерческой неправительственной организации. Каково правило при отсутствии специального исключения?','["Такое участие разрешается после внутреннего голосования организации","Ограничение относится только к депутатам Государственной Думы","Такое участие возможно без уведомления региональных органов","Такое участие запрещено"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Высшее должностное лицо субъекта отказывается оформлять допуск к охраняемой законом тайне. Допускает ли это 414-ФЗ?','["Да, при отсутствии личной заинтересованности","Да, при решении губернатора передать полномочия заместителю","Нет, отказ от прохождения процедуры оформления допуска не допускается","Да, если в регионе мало секретных сведений"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Президент отрешил губернатора от должности. Через три года тот выдвигается вновь в другом субъекте. Какое ограничение действует?','["Трёхлетний запрет только в прежнем субъекте","Пятилетний запрет на выдвижение в любом субъекте после отрешения","Отрешение не влияет на возможность выдвижения","Запрет действует только на ближайшие выборы в прежнем регионе"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Губернатор хочет одновременно замещать должность муниципального служащего. Какое ограничение применяется?','["Несовместимость замещения должности главы субъекта и должности муниципальной службы","Допускается при работе в неполный рабочий день","Допускается, если муниципалитет находится в другом субъекте","Совмещение обязательно для административного центра региона"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Каковы ограничения в отношении иной оплачиваемой деятельности губернатора, финансируемой исключительно зарубежной организацией?','["Иностранное финансирование допускается без ограничений для любых видов деятельности","Ограничение действует только для федеральных депутатов","Такая деятельность автоматически становится безвозмездной","Исключения для научной и творческой работы ограничены правилами об иностранном финансировании"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Высшее должностное лицо региона намерено одновременно стать сенатором Российской Федерации. Какова правовая оценка?','["Допустимо по решению регионального парламента","Допустимо по согласованию Совета Федерации","Совмещение статусов запрещено","Допустимо при отказе от денежного вознаграждения"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 21','https://www.consultant.ru/document/cons_doc_LAW_404070/fba35e0b5dd856684f108185314c3cc5cf33d2e6/','Основание: статья 21 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто представляет субъект Российской Федерации в отношениях с Президентом и Правительством РФ в пределах региональной компетенции?','["Только председатель регионального суда","Высшее должностное лицо субъекта","Руководитель федерального территориального органа","Только председатель муниципальной избирательной комиссии"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Областной парламент принял закон, а губернатор считает его неприемлемым. Какую юридическую возможность закрепляет статья 25?','["Подписать и обнародовать либо отклонить закон субъекта","Отменить закон на неопределённый срок без предусмотренной процедуры","Направить закон на утверждение муниципальным главам","Принять новый федеральный закон вместо областного"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто определяет систему и структуру исполнительных органов субъекта РФ согласно 414-ФЗ?','["Исключительно председатель регионального парламента","Только Совет Федерации","Исключительно Конституционный Суд РФ","Высшее должностное лицо субъекта в соответствии с региональным уставом"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто формирует высший исполнительный орган субъекта РФ и принимает решение о его отставке?','["Центральная избирательная комиссия","Парламент субъекта независимо от распределения полномочий","Высшее должностное лицо субъекта РФ","Председатель Государственной Думы РФ"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный глава не возглавляет исполнительный орган лично. Кто назначает его председателя?','["Главы муниципальных округов на совместном съезде","Высшее должностное лицо субъекта РФ","Председатель Конституционного Суда РФ","Только Правительство РФ"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Кто представляет в региональный парламент ежегодный отчёт о работе высшего исполнительного органа субъекта?','["Высшее должностное лицо субъекта РФ в порядке закона","Руководитель территориального казначейства","Председатель Совета Федерации","Только председатель контрольно-счётного органа"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Губернатор настаивает на внеочередном заседании регионального парламента. Есть ли у него такое право?','["Нет, инициатива может исходить только от регионального суда","Нет, все заседания созывает только Совет Федерации","Да, но только после всероссийского референдума","Да, он вправе требовать созыва внеочередного заседания"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Как губернатор участвует в работе законодательного органа субъекта, если пришёл на заседание?','["С правом решающего голоса как депутат","С правом вето на каждое процедурное голосование","С правом совещательного голоса","С правом заменять голоса отсутствующих депутатов"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Глава муниципалитета не исполняет надлежащим образом переданные государственные полномочия. Какую предупредительную меру вправе применить губернатор?','["Немедленно отменить Конституцию субъекта","Вынести предупреждение или объявить выговор","Издать постановление о прекращении всех муниципальных выборов","Лишить гражданства муниципальных служащих"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Прошёл месяц после выговора главе местной администрации за неисполнение переданных госполномочий, меры устранения причин не приняты. Какое полномочие возникает у губернатора?','["Вправе отрешить главу местной администрации в предусмотренном законом случае","Обязан немедленно распустить региональный парламент","Вправе самостоятельно изменить границы субъекта","Может назначить федерального министра вместо главы администрации"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Региональный глава предлагает досрочно прекратить полномочия законодательного органа субъекта. Возможно ли это?','["Нет, такого полномочия нет ни при каких обстоятельствах","Да, в любой момент без правового основания","Да, только если Дума РФ заранее проголосовала за роспуск","Да, только по основаниям и процедуре, установленным 414-ФЗ"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true),
('Региональная публичная власть: 414-ФЗ','Может ли губернатор обратиться к муниципальному представительному органу с инициативой удаления главы муниципалитета в отставку?','["Нет, такое обращение возможно только в Конституционный Суд","Да, но лишь после изменения бюджета субъекта","Да, в предусмотренных законом случаях","Нет, подобная инициатива есть только у депутатов Государственной Думы РФ"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 25','https://www.consultant.ru/document/cons_doc_LAW_404070/140a37b243e2992ef6038d4b70ff10a14cd537fb/','Основание: статья 25 Федерального закона № 414-ФЗ; применены установленные законом компетенция, срок или порядок.',true)
